{"path":"/app/test_transform_data.py","content":"import csv
import re
from datetime import datetime


INPUT_PATH = "/app/data.csv"
OUTPUT_PATH = "/app/result.csv"

EXPECTED_COLUMNS = [
    "participant_id",
    "first_name",
    "last_name",
    "birth_date",
    "address",
    "phone_number",
    "country",
    "institute",
    "occupation",
    "register_time",
    "postal_code",
    "city",
    "team_name",
]


def read_rows(path):
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def postal_code(address):
    return re.search(r"(\d+)\s*$", address).group(1)


def city(address):
    return address.splitlines()[1].split(",", 1)[0].strip()


def institute_initials(institute):
    return "".join(word[0].upper() for word in re.findall(r"[A-Za-z0-9]+", institute))


def team_name(row):
    return (
        f"{row['first_name'][0].upper()}{row['last_name'][0].upper()}-"
        f"{row['country']}-{institute_initials(row['institute'])}"
    )


def main():
    original = read_rows(INPUT_PATH)
    result = read_rows(OUTPUT_PATH)

    with open(OUTPUT_PATH, newline="", encoding="utf-8") as handle:
        header = next(csv.reader(handle))
    assert header == EXPECTED_COLUMNS, header
    assert len(result) == len(original), (len(result), len(original))

    for source, transformed in zip(original, result):
        for column in EXPECTED_COLUMNS[:10]:
            expected = source[column]
            if column == "birth_date":
                expected = datetime.strptime(expected, "%d %b %Y").strftime("%Y-%m-%d")
            assert transformed[column] == expected, (column, transformed[column], expected)

        assert transformed["postal_code"] == postal_code(source["address"])
        assert transformed["city"] == city(source["address"])
        assert transformed["team_name"] == team_name(source)

    print(f"validated {len(result)} rows")


if __name__ == "__main__":
    main()
"}

